<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {GitBranch,Square,Check,Play} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {parseAgentPlan,type AgentRun,type AgentChange,type AgentTool} from './contract'
import {teamId,parentTools,type AgentTeam} from './team-contract'
import {createAgentTeam,startAgentTeam,stopAgentTeam,recoverAgentTeam,mergeAgentChildren} from './teams'
import {startAgentRun,rollbackAgentChange} from './runtime'
import Sheet from '../components/Sheet.vue'
const props=defineProps<{parent:Document<AgentRun>}>(),store=useLocal(),team=ref<Document<AgentTeam>|null>(null),children=ref<Document<AgentRun>[]>([]),changes=ref<Document<AgentChange>[]>([]),editor=ref(false),busy=ref(false),error=ref(''),selected=ref<string[]>([])
const rows=ref<{instruction:string;roots:string[];tools:AgentTool[];steps:number;automatic:boolean;plan:string}[]>([]),roots=computed(()=>props.parent.value.references.filter(ref=>ref.id===ref.rootId)),remainingCalls=computed(()=>props.parent.value.policy.limits.calls-(props.parent.value.provider?1:0)),calls=computed(()=>rows.value.filter(row=>row.automatic).length),stepTotal=computed(()=>props.parent.value.plan.length+rows.value.reduce((n,row)=>n+row.steps,0))
const toolNames:Record<AgentTool,string>={read:'读取',search:'搜索',compare:'比较',edit:'修改字段',write:'写入',replace:'替换'},status:Record<string,string>={queued:'等待开始',ready:'待继续',running:'执行中',planning:'正在规划',streaming:'正在接收',needs_approval:'等待合并',completed:'已完成',cancelled:'已停止',failed:'未完成',unknown:'待核对'}
const teamStatus=computed(()=>team.value?.value.status==='completed'?(children.value.some(child=>child.value.status==='needs_approval')?'等待合并':children.value.some(child=>['failed','unknown'].includes(child.value.status))?'本轮结束 · 有未完成项':children.value.some(child=>child.value.status==='ready')?'待继续': '已完成'):status[team.value?.value.status||'ready'])
const control=new AbortController();let disposed=false,refreshWork=Promise.resolve()
async function load(){const vault=store.vault;if(!vault)return;const row=await vault.read<AgentTeam>(teamId(props.parent.id));if(disposed||store.vault!==vault)return;if(!row){team.value=null;return}const value=await recoverAgentTeam(vault,row),runs=await vault.readMany<AgentRun>(value.value.children.map(child=>child.runId)),proposals=(await vault.list<AgentChange>('changeSet')).filter(row=>runs.some(run=>run.id===row.value.runId));if(disposed||store.vault!==vault)return;team.value=value;children.value=runs;changes.value=proposals}
function changed(event:Event){const detail=(event as CustomEvent).detail;if(detail?.vaultId!==store.vault?.id||!Array.isArray(detail.ids))return;const ids=new Set([teamId(props.parent.id),...team.value?.value.children.map(child=>child.runId)||[]]);if(detail.ids.some((id:string)=>ids.has(id)||id.startsWith('agent-change:')))refreshWork=refreshWork.then(load).catch(e=>{if(!disposed)error.value=(e as Error).message})}
function add(){if(rows.value.length>=3||!roots.value.length)return;const root=roots.value[rows.value.length%roots.value.length]!;rows.value.push({instruction:'读取 '+String(root.value.name||root.value.title||root.kind),roots:[root.id],tools:['read','search','compare'],steps:1,automatic:false,plan:''})}
function configure(){rows.value=[];add();editor.value=true;error.value=''}
async function create(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const inputs=rows.value.map(row=>({instruction:row.instruction,referenceIds:row.roots,tools:row.tools,steps:row.steps,...(row.automatic?{}:{plan:row.plan.trim()?parseAgentPlan(row.plan,row.steps):row.roots.slice(0,row.steps).map((id,index)=>({id:'read-'+index,tool:'read' as const,arguments:{id}}))})}));const created=await createAgentTeam(vault,props.parent.id,inputs,control.signal);if(disposed)return;team.value=created;editor.value=false;void startAgentTeam(vault,created.id).catch(e=>{if(!disposed)error.value=(e as Error).message});await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function merge(accept:boolean){const vault=store.vault,row=team.value;if(!vault||!row)return;try{await mergeAgentChildren(vault,row.id,[...selected.value],accept,control.signal);selected.value=[];await load()}catch(e){error.value=(e as Error).message}}
async function stop(){if(store.vault&&team.value)try{await stopAgentTeam(store.vault,team.value.id);await load()}catch(e){error.value=(e as Error).message}}
async function resume(run:Document<AgentRun>){if(store.vault)try{await startAgentRun(store.vault,run.id);await load()}catch(e){error.value=(e as Error).message}}
async function rollback(row:Document<AgentChange>){if(store.vault)try{await rollbackAgentChange(store.vault,row.id);await load()}catch(e){error.value=(e as Error).message}}
const fields=(change:AgentChange)=>Object.keys(change.after).filter(field=>canonical(change.before[field]??null)!==canonical(change.after[field]??null))
onMounted(()=>{window.addEventListener('reader-private-commit',changed);void load().catch(e=>error.value=(e as Error).message)})
onUnmounted(()=>{disposed=true;control.abort();window.removeEventListener('reader-private-commit',changed)})
</script>
<template>
 <section class="final-team"><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="!team&&!parent.value.historical&&roots.length&&['ready','completed','needs_approval'].includes(parent.value.status)" @click="configure"><GitBranch :size="16"/>派生子任务</button>
 <template v-if="team"><header><strong>子任务 · {{children.length}}</strong><small>{{teamStatus}} · 并行 {{team.value.limits.parallel}}</small><button v-if="!team.value.historical&&team.value.status!=='cancelled'" @click="stop"><Square :size="16"/>停止整组</button></header><p v-if="team.value.error" class="final-error">{{team.value.error}}</p>
 <article v-for="child in children" :key="child.id" class="final-child"><div class="final-section-title"><strong>{{child.value.instruction}}</strong><small>{{status[child.value.status]}}</small></div><small>{{child.value.cursor}} / {{child.value.policy.limits.steps}} 步 · {{child.value.provider?1:0}} 次调用</small><p v-if="child.value.error" class="final-error">{{child.value.error}}</p><details v-if="child.value.provider?.output"><summary>模型返回</summary><pre>{{child.value.provider.output}}</pre></details><details v-for="result in child.value.results" :key="result.callId"><summary>{{result.summary}}</summary><pre>{{result.data}}</pre></details><button v-if="child.value.status==='ready'&&!team.value.historical" @click="resume(child)"><Play :size="16"/>继续未完成工具</button>
 <article v-for="change in changes.filter(row=>row.value.runId===child.id)" :key="change.id" class="final-child-diff"><label v-if="change.value.status==='proposed'&&child.value.status==='needs_approval'&&!team.value.historical" class="final-check"><input v-model="selected" type="checkbox" :value="change.id">选择合并 · 版本 {{change.value.expectedRevision}}</label><div v-for="field in fields(change.value)" :key="field"><small>{{field}}</small><div class="final-agent-diff"><pre>{{change.value.before[field]}}</pre><pre>{{change.value.after[field]}}</pre></div></div><button v-if="change.value.status==='applied'&&!team.value.historical" @click="rollback(change)">回滚合并</button></article></article>
 <div v-if="selected.length&&!team.value.historical" class="final-grid-actions"><button @click="merge(false)">拒绝选中修改</button><button class="final-primary" @click="merge(true)"><Check :size="16"/>合并 {{selected.length}} 项修改</button></div></template>
 <Sheet v-if="editor" title="派生子任务" @close="editor=false"><form class="final-team-form" @submit.prevent="create"><article v-for="(row,index) in rows" :key="index"><header><strong>子任务 {{index+1}}</strong><button v-if="rows.length>1" type="button" @click="rows.splice(index,1)">移除</button></header><label>任务<textarea v-model="row.instruction" maxlength="20000" required rows="2"></textarea></label><fieldset><legend>引用资料</legend><label v-for="root in roots" :key="root.id" class="final-check"><input v-model="row.roots" type="checkbox" :value="root.id">{{root.value.name||root.value.title||root.kind}}</label></fieldset><label class="final-check"><input v-model="row.automatic" type="checkbox">模型规划 · 最多 1 次调用</label><label>步骤上限<input v-model.number="row.steps" type="number" min="1" :max="parent.value.policy.limits.steps"></label><details><summary>工具权限与直接计划</summary><label v-for="tool in parentTools(parent.value)" :key="tool" class="final-check"><input v-model="row.tools" type="checkbox" :value="tool">{{toolNames[tool]}}</label><label v-if="!row.automatic">工具计划<textarea v-model="row.plan" rows="3" maxlength="100000" placeholder="留空读取所选资料"></textarea></label></details></article><button v-if="rows.length<3" type="button" @click="add">添加子任务</button><small>全组 {{stepTotal}} / {{parent.value.policy.limits.steps}} 步 · 新增 {{calls}} / {{remainingCalls}} 次模型调用</small><p v-if="error" class="final-error" role="alert">{{error}}</p><button class="final-primary" :disabled="busy||!rows.length||stepTotal>parent.value.policy.limits.steps||calls>remainingCalls||rows.some(row=>!row.roots.length)">分配并开始</button></form></Sheet>
 </section>
</template>
<style scoped>.final-team{display:grid;gap:16px}.final-team header,.final-team-form header{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}.final-team small{color:var(--quiet)}.final-child,.final-team-form>article{display:grid;gap:14px;padding:20px;border:1px solid var(--edge);border-radius:12px;background:var(--paper)}.final-child .final-section-title{margin:0}.final-child-diff{padding-top:16px;border-top:1px solid var(--edge);display:grid;gap:16px}.final-team-form{display:grid;gap:20px}.final-team-form label{display:grid;gap:8px}.final-team-form textarea,.final-team-form input[type=number]{width:100%;font:inherit;padding:12px;border-radius:10px;border:1px solid var(--edge);background:var(--canvas);color:var(--ink)}.final-agent-diff{display:grid;grid-template-columns:1fr 1fr;gap:12px}.final-agent-diff pre{border:1px solid var(--edge);padding:12px;border-radius:8px;max-width:100%;overflow-wrap:anywhere;white-space:pre-wrap}pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;max-height:340px}@media(max-width:767px){.final-agent-diff{grid-template-columns:1fr}}</style>
